WITH metrics AS (SELECT id, device_code, reading_ts, pressure, status_bits, firmware, COUNT(temp_c) OVER (PARTITION BY device_code ORDER BY pressure, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_count_temp_c, MAX(temp_c) OVER (PARTITION BY device_code ORDER BY pressure, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_max_temp_c, AVG(temp_c) OVER (PARTITION BY device_code ORDER BY pressure, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_avg_temp_c, COUNT(status_bits) OVER (PARTITION BY device_code ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 1800 PRECEDING AND CURRENT ROW) AS status_bits_count_30m FROM device_readings) SELECT id, reading_ts, pressure, status_bits, firmware, last3_max_temp_c, last3_avg_temp_c, status_bits_count_30m FROM metrics ORDER BY last3_max_temp_c NULLS LAST, status_bits_count_30m DESC;
